#include <stdio.h>

#define MAXN 100005
#define LOG 20

int N, Q;
int p[MAXN];
int up[LOG][MAXN];
int depth[MAXN];
int head[MAXN], to[MAXN], nxt[MAXN], edge = 0;
int tin[MAXN], tout[MAXN];
int activeAt[MAXN];
int bit[MAXN];
int active_count = 0;

void bit_add(int idx, int delta) {
    for (; idx <= N; idx += idx & -idx) bit[idx] += delta;
}

int bit_sum(int idx) {
    int s = 0;
    for (; idx > 0; idx -= idx & -idx) s += bit[idx];
    return s;
}

int bit_kth(int k) {
    int idx = 0;
    int mask = 1;
    while ((mask << 1) <= N) mask <<= 1;
    for (int step = mask; step; step >>= 1) {
        int next = idx + step;
        if (next <= N && bit[next] < k) {
            idx = next;
            k -= bit[next];
        }
    }
    return idx + 1;
}

int find_containing(int pos) {
    int cnt = bit_sum(pos);
    if (cnt == 0) return 0;
    int at = bit_kth(cnt);
    int node = activeAt[at];
    if (node != 0 && tout[node] >= pos) return node;
    return 0;
}

int first_in_range(int L, int R) {
    int before = bit_sum(L - 1);
    if (active_count == before) return 0;
    int pos = bit_kth(before + 1);
    if (pos <= R) return pos;
    return 0;
}

int kth_ancestor(int v, int k) {
    for (int j = 0; j < LOG; j++) {
        if (k & (1 << j)) v = up[j][v];
    }
    return v;
}

int main() {
    scanf("%d", &N);

    for (int i = 2; i <= N; i++) {
        scanf("%d", &p[i]);
    }

    for (int i = 2; i <= N; i++) {
        int par = p[i];
        edge++;
        to[edge] = i;
        nxt[edge] = head[par];
        head[par] = edge;
    }

    depth[1] = 0;
    up[0][1] = 0;
    for (int i = 2; i <= N; i++) {
        depth[i] = depth[p[i]] + 1;
        up[0][i] = p[i];
    }

    for (int j = 1; j < LOG; j++) {
        up[j][0] = 0;
        for (int i = 1; i <= N; i++) {
            int mid = up[j - 1][i];
            up[j][i] = mid ? up[j - 1][mid] : 0;
        }
    }

    int stack_v[2 * MAXN], stack_state[2 * MAXN];
    int top = 0;
    stack_v[top] = 1;
    stack_state[top] = 0;
    top++;

    int timer = 0;
    while (top > 0) {
        top--;
        int v = stack_v[top];
        int state = stack_state[top];

        if (state == 0) {
            tin[v] = ++timer;
            stack_v[top] = v;
            stack_state[top] = 1;
            top++;

            for (int e = head[v]; e; e = nxt[e]) {
                int u = to[e];
                stack_v[top] = u;
                stack_state[top] = 0;
                top++;
            }
        } else {
            tout[v] = timer;
        }
    }

    scanf("%d", &Q);

    while (Q--) {
        int type;
        scanf("%d", &type);

        if (type == 1) {
            int v, k;
            scanf("%d %d", &v, &k);

            int pred = find_containing(tin[v]);
            int start = v;

            if (pred != 0 && pred != v) {
                k--;
                start = pred;
            }

            int ans = kth_ancestor(start, k);
            printf("%d\n", ans);
        } else {
            int v;
            scanf("%d", &v);

            int pred = find_containing(tin[v]);
            if (pred == 0) {
                int L = tin[v], R = tout[v];

                while (1) {
                    int pos = first_in_range(L, R);
                    if (pos == 0) break;

                    int node = activeAt[pos];
                    activeAt[pos] = 0;
                    bit_add(pos, -1);
                    active_count--;
                }

                activeAt[L] = v;
                bit_add(L, 1);
                active_count++;
            }
        }
    }

    return 0;
}
